    ((a,b,t) -> tuplePlus(a,tupleMultiplyByNumber(tupleMinus(b,a),t))) AS mix,
    ((p,s) -> arrayMap(u -> arrayMap(v -> arrayMap(rad -> multiIf(s.1=0, clamp(0.5-(rad-1.0)*least(s.3.3,s.3.4)/aa,0.,1.), s.1=3, clamp(0.5-(abs(rad-1.0)*least(s.3.3,s.3.4)-s.4)/aa,0.,1.), exp(-rad*rad*2.0)), [sqrt(pow(u/s.3.3,2)+pow(v/s.3.4,2))])[1], [-(p.1-s.3.1)*s.3.6 + (p.2-s.3.2)*s.3.5])[1], [(p.1-s.3.1)*s.3.5 + (p.2-s.3.2)*s.3.6])[1]) AS oval,
    ((p,s) -> arrayMap(dx -> arrayMap(dy -> arrayMap(t -> clamp(0.5-(hypot(p.1-s.3.1-t*dx,p.2-s.3.2-t*dy)-s.4*0.5)/aa,0.,1.), [clamp(((p.1-s.3.1)*dx+(p.2-s.3.2)*dy)/greatest(dx*dx+dy*dy,0.00001),0.,1.)])[1], [s.3.4-s.3.2])[1], [s.3.3-s.3.1])[1]) AS segment,
    ((acc,p,s) -> arrayMap(alpha -> arrayMap(grad -> arrayMap(ink -> mix(acc,ink,alpha), [mix(s.6,s.7,grad)])[1], [clamp((p.2-s.2.2)/greatest(s.2.4-s.2.2,0.001),0.,1.)])[1], [s.5*multiIf(s.1=2,toFloat64(pointInPolygon(p,s.8)),s.1=1,segment(p,s),oval(p,s))])[1]) AS paint,
