    (p -> arrayMap(depth -> arrayMap(rip -> arrayMap(fine -> arrayMap(base -> arrayMap(band -> arrayMap(glint -> arrayMap(wat -> mix(wat,(.92,.66,.35),clamp(glint,0.,.8)), [tuplePlus(base,((rip*.018+fine*.009),(rip*.029+fine*.014),(rip*.027+fine*.014)))])[1], [band*(.13+.35*pow(greatest(rip,0.),9.)+.13*pow(greatest(fine,0.),16.))])[1], [exp(-pow((p.1-1220.-16.*sin(p.2*.043))/(25.+depth*119.),2))])[1], [mix((.28,.43,.43),(.045,.23,.29),pow(depth,.55))])[1], [sin(p.2*1.16+p.1*.036+3.*sin(p.1*.004-p.2*.012))])[1], [sin(p.2*(0.6-depth*.39)+sin(p.1*.012+p.2*.021)*2.5)])[1], [clamp((p.2-508.)/492.,0.,1.)])[1]) AS water,
    ((p,initial) -> arrayFold((acc,s) -> paint(acc,p,s),
        arrayFilter(s -> p.1>=s.2.1 AND p.1<=s.2.3 AND p.2>=s.2.2 AND p.2<=s.2.4,
            arrayMap(i -> shapes[i], arrayFilter(i -> i>=971 AND i<=2479,tiles[tileAt(p)]))),initial)) AS hero,
    (p -> if(p.2>824.,
        mix(water(p),hero((p.1+5.*sin(p.2*.13)+2.*sin(p.2*.39),824.-(p.2-824.)*1.62),water(p)),
            .24*exp(-(p.2-824.)/190.)*(.7+.3*sin(p.2*.64))),
        if(p.2>508.,water(p),sky(p)))) AS backdrop
SELECT
    clamp(avg(col.1),0.,1.) AS r,
    clamp(avg(col.2),0.,1.) AS g,
    clamp(avg(col.3),0.,1.) AS b,
    pixel % W AS x,
    intDiv(pixel,W) AS y
FROM (
    SELECT pixel,
        tuplePlus(tupleMultiplyByNumber(draw(p,backdrop(p)),vignette),
                  (grain,grain,grain)) AS col
    FROM (
        SELECT intDiv(number,spp) AS pixel,
            number%spp AS sample,
            ((pixel%W+samplePattern[sample+1].1)*1600.0/W,
             (intDiv(pixel,W)+samplePattern[sample+1].2)*1000.0/H) AS p,
            1.-.15*pow(clamp(hypot((p.1-800.)/1000.,(p.2-480.)/760.),0.,1.),2.) AS vignette,
            ((cityHash64(pixel,sample,42)%65536)/65535.-.5)*.008 AS grain
        FROM numbers_mt(W*H*spp)
    )
)
GROUP BY pixel
SETTINGS max_threads=8, max_block_size=256,
         max_ast_elements=1000000, max_expanded_ast_elements=2000000,
         short_circuit_function_evaluation='force_enable'
FORMAT PNG

